/* Mote — Playdate: the games linked into the pdex (table generated by
 * scripts/build-playdate.sh into mote_pd_games.c). */
#ifndef MOTE_PD_GAMES_H
#define MOTE_PD_GAMES_H
#include "mote_api.h"

typedef struct {
    const char *stem;                                   /* save folder name */
    const MoteGameVtbl *(*reg)(const MoteApi *api);
    const char *const *name;                            /* MOTE_GAME_META, or NULL */
    const void *icon;                                   /* icon blob, or NULL */
} MotePdGame;

extern const MotePdGame mote_pd_games[];
extern const int mote_pd_ngames;

#endif
